export function getPostBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find((p) => p.slug === slug);
}

export function getRelatedPosts(slug: string, count = 4): BlogPost[] {
  const current = blogPosts.find((p) => p.slug === slug);
  if (!current) return blogPosts.filter((p) => p.slug !== slug).slice(0, count);
  const sameCategory = blogPosts.filter(
    (p) => p.slug !== slug && p.category === current.category
  );
  const others = blogPosts.filter(
    (p) => p.slug !== slug && p.category !== current.category
  );
  return [...sameCategory, ...others].slice(0, count);
}

export function slugifyFaq(question: string): string {
  return question
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .slice(0, 80);
}

export type RichFaq = FAQ & {
  postSlug: string;
  postTitle: string;
  postCategory: string;
  postPublishedAt: string;
  postImage: string;
  postImageAlt: string;
  postExcerpt: string;
  faqSlug: string;
};

export function getAllFaqs(): RichFaq[] {
  return blogPosts.flatMap((post) =>
    (post.faqs ?? []).map((faq) => ({
      ...faq,
      postSlug: post.slug,
      postTitle: post.title,
      postCategory: post.category,
      postPublishedAt: post.publishedAt,
      postImage: post.image,
      postImageAlt: post.imageAlt,
      postExcerpt: post.excerpt,
      faqSlug: slugifyFaq(faq.question),
    }))
  );
}
